  function updateAlgorithm(){const key=$('algorithm').value,d=descriptions[key];setText('algorithm-type',d[0]);setText('algorithm-badge',d[1]);setText('algorithm-description',d[2]);setText('algorithm-formula',d[3]);setText('footer-algorithm',E.algorithms[key].name.toUpperCase());setText('quick-algorithm-name',learning?'Q-learning':E.algorithms[key].name);const disabled=['bfs','dfs','dijkstra','bidir','dstar'].includes(key);$('heuristic').disabled=disabled;$('weight').disabled=disabled;globalThis.MetroSelect?.sync();}
  function resetSearch(text='Path cleared. Your city is ready for a new journey.',quiet=false){playing=false;search=null;policyResult=null;pulse=[];announced=false;city?.setSearch(new Set(),new Set(),null);setState('Ready');setRunButton();renderStats();drawPulse();drawMinimap();if(text)message(text);if(!quiet)log(text);}
  function selectTab(value){if(value===learning)return;playing=false;training=false;learning=value;document.body.classList.toggle('learning-mode',value);setText('quick-algorithm-name',value?'Q-learning':E.algorithms[$('algorithm').value].name);$('quick-algorithm').setAttribute('aria-label',value?'Agent settings':'Choose search algorithm');$('tab-search').classList.toggle('active',!value);$('tab-learning').classList.toggle('active',value);$('tab-search').setAttribute('aria-selected',String(!value));$('tab-learning').setAttribute('aria-selected',String(value));$('search-settings').hidden=value;$('learning-settings').hidden=!value;$('rl-results').hidden=!value;$('nav-simulation').classList.toggle('active',!value);$('nav-learning').classList.toggle('active',value);setRunButton();setState('Ready');city?.setSearch(value?new Set():search?.visited||new Set(),value?new Set():search?.frontier||new Set(),value?policyResult?.path||null:search?.path||null);refreshLayer();renderStats();drawMinimap();drawPulse();}
  function selectTool(value){tool=value;document.querySelectorAll('[data-tool]').forEach(b=>{b.classList.toggle('active',b.dataset.tool===value);b.setAttribute('aria-pressed',String(b.dataset.tool===value));});if(['highway','traffic','mud','raise','lower'].includes(value)){$('map-tools').classList.add('expanded');$('tools-expand').setAttribute('aria-expanded','true');}city?.setTool(value);if(value!=='view')message(`${tools.find(t=>t[0]===value)[2]}. Click or drag across the city to edit.`);updateBuilder();}
