    const radius=tool==='start'||tool==='goal'?0:(brushSize-1)/2,targets=[];
    // A corner bridge keeps diagonal freehand strokes connected for 4-way search.
    if(strokeLast&&center.x!==strokeLast.x&&center.z!==strokeLast.z&&['road','highway','traffic','mud'].includes(tool))targets.push({x:center.x,z:strokeLast.z});
