      const x=target.x+dx,z=target.z+dz;let hit=grid.worldToCell(x,z);
      if(!hit.inBounds){if(tool==='erase'||event.shiftKey)continue;try{const growth=grid.expandToWorld(x,z);grew=grew||growth.changed;hit=grid.worldToCell(x,z);}catch(error){if(!strokeLimitReported){strokeLimitReported=true;toast(error.message,'warn');setText('build-help',error.message);}continue;}}
