  function renderStats(){const s=learning?null:search,visited=s?.visited.size||0,walkable=grid.count-grid.types.reduce((a,t)=>a+(t===1),0),path=learning?(policyResult?.reached?policyResult.path:null):s?.path,cost=learning?policyResult?.cost:s?.cost;const coverage=Math.min(100,visited/Math.max(1,walkable)*100);
    $('stat-visited').innerHTML=visited.toLocaleString()+`<small>/ ${grid.count.toLocaleString()}</small>`;setText('stat-frontier',s?.frontier.size||0);setText('stat-path',path?path.length:'—');setText('stat-cost',path?Number(cost).toFixed(1):'—');$('stat-time').innerHTML=(s?.elapsed||0).toFixed(1)+'<small>ms</small>';$('stat-coverage').innerHTML=coverage.toFixed(1)+'<small>%</small>';$('coverage-bar').style.width=coverage+'%';setText('quick-visited',visited.toLocaleString());setText('quick-cost',path?Number(cost).toFixed(1):'—');document.body.classList.toggle('has-search',!!(visited||path));
    const cursor=s?.cursor||0,total=s?.history.length||0;setText('history-label',`STEP ${String(cursor).padStart(3,'0')} / ${String(total).padStart(3,'0')}`);$('history').max=Math.max(1,total);$('history').value=cursor;$('history').disabled=!total;$('back-btn').disabled=learning||!cursor;setText('playback-label',learning?(training?'AGENT IS LEARNING':'REINFORCEMENT LEARNING'):playing?'DISCOVERING THE WAY':s?.done?(s.path?'JOURNEY COMPLETE':'NO ROUTE FOUND'):cursor?'SEARCH PLAYBACK':'READY TO EXPLORE');setText('route-badge',learning&&policyResult?.reached?'POLICY FOUND':s?.done?(s.path?'CONNECTED':'NO ROUTE'):playing?'EXPLORING':cursor?'IN PROGRESS':'NOT STARTED');}
  function drawMinimap(canvas=$('minimap'),route=learning?policyResult?.path:search?.path,visited=learning?null:search?.visited,frontier=learning?null:search?.frontier){const x=canvas.getContext('2d'),w=canvas.width,h=canvas.height,n=grid.size;x.fillStyle='#101e19';x.fillRect(0,0,w,h);const cell=Math.min((w-24)/n,(h-18)/n),ox=(w-n*cell)/2,oy=(h-n*cell)/2,colors=['#30473d','#60746b','#41675b','#8e7750','#71624e'];for(let i=0;i<grid.count;i++){if(grid.freeBuild&&!grid.developed[i])continue;x.fillStyle=colors[grid.types[i]];if(visited?.has(i))x.fillStyle='#549488';if(frontier?.has(i))x.fillStyle='#d2ad70';x.fillRect(ox+(i%n)*cell,oy+(i/n|0)*cell,Math.max(1,cell-.5),Math.max(1,cell-.5));}if(route?.length){x.strokeStyle='#a9efc8';x.lineWidth=Math.max(1.2,cell*.42);x.lineJoin='round';x.beginPath();route.forEach((i,k)=>{const px=ox+(i%n+.5)*cell,py=oy+((i/n|0)+.5)*cell;k?x.lineTo(px,py):x.moveTo(px,py);});x.stroke();}[[grid.start,'#baf3d3'],[grid.goal,'#ddadc9']].forEach(([i,color])=>{x.fillStyle=color;x.beginPath();x.arc(ox+(i%n+.5)*cell,oy+((i/n|0)+.5)*cell,Math.max(2.4,cell*.65),0,Math.PI*2);x.fill();});}
