  function makeLearner(){learner=new E.QLearner(grid,{alpha:Number($('alpha').value),gamma:Number($('gamma').value),epsilon:Number($('epsilon').value),decay:Number($('decay').value),maxSteps:Number($('max-steps').value),diagonal:$('diagonal').checked});policyResult=null;return learner;}
  function toggleTraining(){if(training){training=false;setState('Paused');log('Agent training paused.');}else{validateLearning();if(!learner)makeLearner();if(learner.episodes>=Number($('episodes').value)){makeLearner();}training=true;playing=false;city?.setPath(null);setState('Learning');log(`Q-learning started · target ${$('episodes').value} episodes.`);message('Learning through the city. Each journey makes the next decision a little wiser.');closeDrawers();}setRunButton();}
  function validateLearning(){[['episodes',10,100000,3000],['max-steps',10,10000,900],['batch-size',1,100,10],['epsilon',.01,1,1]].forEach(([id,min,max,fallback])=>{const v=Number($(id).value);$(id).value=String(Math.max(min,Math.min(max,Number.isFinite(v)?v:fallback)));});}
  function clearLearningStats(){['rl-episodes','rl-success'].forEach(id=>setText(id,'0'));setText('rl-reward','—');setText('rl-epsilon',Number($('epsilon').value).toFixed(3));setText('training-percent','0%');$('training-progress').value=0;}
  function renderLearning(){if(!learner)return;const max=Number($('episodes').value),last=learner.rewards.slice(-50),avg=last.reduce((a,b)=>a+b,0)/Math.max(1,last.length);setText('rl-episodes',learner.episodes.toLocaleString());setText('rl-epsilon',learner.epsilon.toFixed(3));setText('rl-reward',avg.toFixed(1));setText('rl-success',learner.successes.toLocaleString());setText('training-percent',Math.min(100,Math.round(learner.episodes/max*100))+'%');$('training-progress').max=max;$('training-progress').value=learner.episodes;refreshLayer();drawPulse();renderStats();if(learner.episodes>=max&&training){training=false;setRunButton();setState('Trained');message(`Training complete. ${learner.episodes.toLocaleString()} episodes, ${learner.successes.toLocaleString()} successful explorations. Test the learned policy.`);log(`Training complete · ${learner.episodes} episodes · avg reward ${avg.toFixed(1)}.`);toast('Training complete. Test what the agent learned.');}}
  function testPolicy(){training=false;setRunButton();if(!learner?.episodes){toast('Train the agent first, then test its policy.','warn');return;}if(learner.version!==grid.version){learner=null;toast('The city changed. Train a new policy first.','warn');return;}policyResult=learner.rollout();city?.setPath(policyResult.path);drawMinimap();renderStats();if(policyResult.reached){setState('Policy found');message(`The agent found its own way. Cost ${policyResult.cost.toFixed(2)}; learned policies do not guarantee optimality.`);log(`Learned policy reached destination · ${policyResult.path.length} cells.`);}else{setState('Keep learning');message(`The policy explored ${policyResult.path.length} cells, then stalled. Increase episodes or exploration and train again.`);log('Policy test stalled before destination. More training may help.','warn');toast('The agent needs more practice. Its partial route is shown.','warn');}}
