  async function compare(){flushEdits();if(learning)selectTab(false);showModal('Nine minds. One city.',`<p>Running every algorithm on the same city, endpoints, and movement settings.</p><div class="comparison-loading"><span class="loading-mark" style="margin:35px auto"></span></div>`,true);comparisons=[];const token=comparisonToken,snapshot=E.Grid.fromJSON(grid.serialize()),searchOptions=options(),results=[];
    for(const algorithm of Object.keys(E.algorithms)){await new Promise(resolve=>setTimeout(resolve,0));if(token!==comparisonToken||!$('modal').open)return;const s=new E.SearchSession(snapshot,algorithm,searchOptions);s.finish();results.push({algorithm,visited:s.visited.size,frontier:s.frontier.size,path:s.path?.length||0,cost:s.path?s.cost:Infinity,ms:s.elapsed,route:s.path,note:s.note,seed:snapshot.seed,size:snapshot.size});}comparisons=results;
    const reachable=comparisons.filter(r=>r.path),cheapest=Math.min(...reachable.map(r=>r.cost)),fewest=Math.min(...reachable.map(r=>r.visited)),maxNodes=Math.max(1,...comparisons.map(r=>r.visited)),minMS=Math.min(...reachable.map(r=>r.ms));const minCostRow=reachable.find(r=>r.cost===cheapest),minNodesRow=reachable.find(r=>r.visited===fewest);
    $('modal-content').innerHTML=`<div class="comparison-intro"><span>${grid.size} × ${grid.size} grid · same terrain · ${$('diagonal').checked?'8':'4'} directions</span><div class="comparison-summary">${minCostRow?`<span>Lowest cost · ${E.algorithms[minCostRow.algorithm].short}</span><span>Fewest explored · ${E.algorithms[minNodesRow.algorithm].short}</span>`:'<span>No route exists in this city</span>'}</div></div><div class="compare-grid">${comparisons.map((r,i)=>`<article class="compare-card ${r.path&&Math.abs(r.cost-cheapest)<.0001?'winner':''}"><h3>${E.algorithms[r.algorithm].short}<span>${r.path&&Math.abs(r.cost-cheapest)<.0001?'LOWEST COST':r.path&&r.visited===fewest?'FEWEST NODES':''}</span></h3><canvas id="compare-map-${i}" width="240" height="105" aria-label="${escape(E.algorithms[r.algorithm].name)} route"></canvas><div class="compare-values"><span><b>${r.visited}</b>EXPLORED</span><span><b>${r.path?r.cost.toFixed(1):'—'}</b>COST</span><span><b>${r.ms.toFixed(1)}</b>MS</span></div><div class="compare-bar"><i style="width:${r.visited/maxNodes*100}%"></i></div><small>${r.path?(r.note||(r.algorithm==='bfs'?'Fewest moves; terrain costs differ.':r.algorithm==='dfs'||r.algorithm==='greedy'?'Does not guarantee the lowest cost.':'Weighted route through the same city.')):'No reachable route.'}</small></article>`).join('')}</div><div class="comparison-footer"><p>Timing measures algorithm work in this browser. Theta* uses any-angle segments; BFS minimizes moves. Compare their objectives as well as their numbers. JPS uses A* on weighted terrain.</p><button class="button export-button" data-action="export-csv">${icon('download')}Download comparison</button></div>`;comparisons.forEach((r,i)=>drawMinimap($('compare-map-'+i),r.route,null,null));log('Nine-algorithm comparison complete.');}
